const UNIT_SHORT: Record<TimeUnit, string> = { seconds: 's', minutes: 'min', hours: 'h', days: 'd' };
const UNIT_ONE: Record<TimeUnit, string> = { seconds: 'second', minutes: 'minute', hours: 'hour', days: 'day' };

/** Whether the flow is Salesforce automation (a Flow, a save order): nothing to simulate. */
export function isAutomationFlow(diagram: ProcessFlowDiagram): boolean {
  return diagram.platform === 'salesforce';
}

/** The flow's time unit; minutes when it has none, as the simulator reads it. */
export function flowTimeUnit(diagram: ProcessFlowDiagram): TimeUnit {
  return diagram.timeUnit ?? 'minutes';
}

/** "min" for minutes: the unit after a number. */
export function unitShort(unit: TimeUnit): string {
  return UNIT_SHORT[unit];
}

/** "minute" for minutes: the unit in "per minute". */
export function unitSingular(unit: TimeUnit): string {
  return UNIT_ONE[unit];
}

function number(value: number): string {
  return Number.isInteger(value) ? String(value) : String(Number(value.toFixed(2)));
}

/** A distribution in a few words: "2–5 min (most often 3)", "about 4 min", "5 min". */
export function describeDistribution(distribution: Distribution, unit: TimeUnit): string {
  const u = UNIT_SHORT[unit];
  switch (distribution.type) {
    case 'fixed':
      return `${number(distribution.value)} ${u}`;
    case 'exponential':
      return `about ${number(distribution.mean)} ${u} on average`;
    case 'uniform':
      return `${number(distribution.min)}–${number(distribution.max)} ${u}`;
    case 'triangular':
      return `${number(distribution.min)}–${number(distribution.max)} ${u} (most often ${number(distribution.mode)})`;
    case 'normal':
      return `about ${number(distribution.mean)} ± ${number(distribution.sd)} ${u}`;
    case 'lognormal':
      return `about ${number(distribution.mean)} ${u} (± ${number(distribution.sd)}, long tail)`;
  }
}

/** The distribution's average, in the time unit. */
export function distributionMean(distribution: Distribution): number {
  switch (distribution.type) {
    case 'fixed':
      return distribution.value;
    case 'exponential':
    case 'normal':
    case 'lognormal':
      return distribution.mean;
    case 'uniform':
      return (distribution.min + distribution.max) / 2;
    case 'triangular':
      return (distribution.min + distribution.mode + distribution.max) / 3;
  }
}

