export type FlowFamily = 'data' | 'logic' | 'interaction' | 'start' | 'end' | 'neutral';

/** The shape of an element's icon tile, as Flow Builder draws it: decisions are diamonds. */
export type FlowTileShape = 'square' | 'diamond' | 'circle';

