const NEW_NODE: Record<FlowNodeType, Omit<FlowNode, 'id'>> = {
  start: { type: 'start', label: 'Arrivals', arrivals: { type: 'exponential', mean: 5 }, source: 'user' },
  step: { type: 'step', label: 'New step', duration: { type: 'triangular', min: 2, mode: 3, max: 5 }, capacity: 1, source: 'user' },
  decision: { type: 'decision', label: 'Decision?', source: 'user' },
  end: { type: 'end', label: 'Done', source: 'user' },
};

/** A Salesforce flow's new node: the label alone, no numbers. */
const NEW_AUTOMATION_NODE: Record<FlowNodeType, Omit<FlowNode, 'id'>> = {
  start: { type: 'start', label: 'Start', source: 'user' },
  step: { type: 'step', label: 'New step', source: 'user' },
  decision: { type: 'decision', label: 'Decision?', source: 'user' },
  end: { type: 'end', label: 'End', source: 'user' },
};

/** A new node the user adds: a start, step, decision or end with workable numbers (none in a Salesforce flow), marked as the user's. */
export function addFlowNode(diagram: ProcessFlowDiagram, type: FlowNodeType): { diagram: ProcessFlowDiagram; id: string } {
  const id = uniqueName(diagram.nodes.map((node) => node.id), type);
  const node = (isAutomationFlow(diagram) ? NEW_AUTOMATION_NODE : NEW_NODE)[type];
  return { diagram: { ...diagram, nodes: [...diagram.nodes, { id, ...node }] }, id };
}

/** A new Flow element the user adds to a Salesforce flow: "New Get Records", typed, marked as the user's (a decision or loop branches). */
export function addFlowElement(diagram: ProcessFlowDiagram, elementType: string): { diagram: ProcessFlowDiagram; id: string } {
  const name = elementTypeLabel(elementType);
  const id = uniqueName(diagram.nodes.map((node) => node.id), `New_${name.replace(/[^A-Za-z0-9]+/g, '_')}`);
  const type: FlowNodeType = elementType === 'decisions' || elementType === 'loops' ? 'decision' : 'step';
  return { diagram: { ...diagram, nodes: [...diagram.nodes, { id, type, label: `New ${name}`, elementType, source: 'user' }] }, id };
}

type NodePatch = Partial<Omit<FlowNode, 'id'>>;

/** A node changed; cleared text and an unset capacity or resource are left out of the file. */
export function updateFlowNode(diagram: ProcessFlowDiagram, id: string, patch: NodePatch): ProcessFlowDiagram {
  return { ...diagram, nodes: diagram.nodes.map((node) => (node.id === id ? withoutEmpty({ ...node, ...patch }) : node)) };
}

/** A node removed, with the flows into and out of it and its position. */
export function deleteFlowNode(diagram: ProcessFlowDiagram, id: string): ProcessFlowDiagram {
  const positions = diagram.layout?.positions;
  const rest = positions ? Object.fromEntries(Object.entries(positions).filter(([nodeId]) => nodeId !== id)) : undefined;
  return {
    ...diagram,
    nodes: diagram.nodes.filter((node) => node.id !== id),
    flows: diagram.flows.filter((flow) => flow.from !== id && flow.to !== id),
    ...(rest ? { layout: { ...diagram.layout, positions: rest } } : {}),
  };
}

/**
 * A flow the user draws. Out of a decision, the branches share evenly (the
 * user then sets the shares; a Salesforce decision has none); a start or step
 * keeps one flow out, so a new one replaces its old one (a fault flow stays).
 */
export function addFlow(diagram: ProcessFlowDiagram, input: { from: string; to: string }): { diagram: ProcessFlowDiagram; id: string } {
  const from = diagram.nodes.find((node) => node.id === input.from);
  if (!from || from.type === 'end' || input.from === input.to) return { diagram, id: '' };
  const id = uniqueName(diagram.flows.map((flow) => flow.id), `${input.from}-${input.to}`);
  if (from.type === 'decision' && isAutomationFlow(diagram)) {
    return { diagram: { ...diagram, flows: [...diagram.flows, { id, from: input.from, to: input.to }] }, id };
  }
  if (from.type === 'decision') {
    const branches = [...diagram.flows.filter((flow) => flow.from === from.id), { id, from: input.from, to: input.to }];
    const share = Number((1 / branches.length).toFixed(4));
    const shared = new Map(branches.map((flow, index) => [flow.id, index === branches.length - 1 ? Number((1 - share * (branches.length - 1)).toFixed(4)) : share]));
    const others = diagram.flows.filter((flow) => flow.from !== from.id);
    return { diagram: { ...diagram, flows: [...others, ...branches.map((flow) => ({ ...flow, share: shared.get(flow.id) }))] }, id };
  }
  const others = diagram.flows.filter((flow) => flow.from !== from.id || flow.fault || flow.launch);
  return { diagram: { ...diagram, flows: [...others, { id, from: input.from, to: input.to }] }, id };
}

type FlowPatch = Partial<Omit<Flow, 'id' | 'from' | 'to'>>;

export function updateFlow(diagram: ProcessFlowDiagram, id: string, patch: FlowPatch): ProcessFlowDiagram {
  return { ...diagram, flows: diagram.flows.map((flow) => (flow.id === id ? withoutEmpty({ ...flow, ...patch }) : flow)) };
}

export function deleteFlow(diagram: ProcessFlowDiagram, id: string): ProcessFlowDiagram {
  return { ...diagram, flows: diagram.flows.filter((flow) => flow.id !== id) };
}

/** A shared resource (staff who work several steps). */
export function addResource(diagram: ProcessFlowDiagram): { diagram: ProcessFlowDiagram; id: string } {
  const id = uniqueName(diagram.resources.map((resource) => resource.id), 'staff');
  return { diagram: { ...diagram, resources: [...diagram.resources, { id, label: 'Staff', capacity: 1, source: 'user' }] }, id };
}

export function updateResource(diagram: ProcessFlowDiagram, id: string, patch: Partial<Omit<FlowResource, 'id'>>): ProcessFlowDiagram {
  return { ...diagram, resources: diagram.resources.map((resource) => (resource.id === id ? withoutEmpty({ ...resource, ...patch }) : resource)) };
}

/** A resource removed; the steps that used it go back to their own capacity. */
export function deleteResource(diagram: ProcessFlowDiagram, id: string): ProcessFlowDiagram {
  return {
    ...diagram,
    resources: diagram.resources.filter((resource) => resource.id !== id),
    nodes: diagram.nodes.map((node) => (node.resource === id ? withoutEmpty({ ...node, resource: undefined }) : node)),
  };
}

/** The run settings changed (a run is added with defaults when there was none). */
export function updateRun(diagram: ProcessFlowDiagram, patch: Partial<FlowRun>): ProcessFlowDiagram {
  const run = { duration: diagram.run?.duration ?? defaultRunDuration(flowTimeUnit(diagram)), ...diagram.run, ...patch };
  return { ...diagram, run: withoutEmpty(run) };
}

/** A sensible run length when the file has none: a working day in the flow's unit. */
export function defaultRunDuration(unit: TimeUnit): number {
  return { seconds: 8 * 3600, minutes: 8 * 60, hours: 8 * 5, days: 60 }[unit];
}

/** Optional values cleared in the editor are left out of the file. */
function withoutEmpty<T extends object>(value: T): T {
  return Object.fromEntries(Object.entries(value).filter(([, entry]) => entry !== undefined && entry !== '')) as T;
}
